files.main.nex:
module histories::aliases;enum Maybe{Some(value:file);None;}struct Packet{files:list<file>;result:result<file>;tag:Maybe;}
server fn main()->i64 !{task,fs}{let f:file=unwrap(file_open_read("input"));let p:Packet=Packet([f,f],ok(f),Maybe::Some(f));let alias:file=unwrap(p.result);
assert(alias==p.files[0]);assert(unwrap(file_read(alias,3))==utf8_bytes("abc"));assert(unwrap(file_read(p.files[1],3))==utf8_bytes("def"));assert(file_close(alias));assert(!file_is_open(f));return 42;}

client fn client_value()->i64{return 42;}
test fn pure_answer()->unit{assert(42>41);}

